css:
.container {
  width: 100%;
  height: 100%;
  background:
    linear-gradient(135deg, #18181b 25%, transparent 25%) -20px 0,
    linear-gradient(225deg, #18181b 25%, transparent 25%) -20px 0,
    linear-gradient(315deg, #18181b 25%, transparent 25%),
    linear-gradient(45deg, #18181b 25%, transparent 25%),
    linear-gradient(90deg, #3b82f6 50%, transparent 50%),
    linear-gradient(180deg, #3b82f6 50%, #2563eb 50%);
  background-size:
    40px 40px,
    40px 40px,
    40px 40px,
    40px 40px,
    40px 40px,
    100% 100%;
  background-color: #1e293b;
}
